import React, { useState } from "react";
import styled from "styled-components";
import { useTranslation } from "react-i18next";
import "react-image-lightbox/style.css";
import Lightbox from "react-image-lightbox";

const Container = styled.div`
  padding: 20px;
  text-align: center;
`;

const Title = styled.h2`
  font-size: 50px;
  font-weight: bold;
  margin-bottom: 1rem;
  color: #1e3a8a;
`;

const SectionTitle = styled.h3`
  font-size: 36px;
  font-weight: bold;
  margin-top: 1rem;
  color: #1e40af;
`;

const ImageWrapper = styled.div`
  display: inline-block;
  margin: 10px;
`;

const StyledImage = styled.img`
  max-width: 100%;
  height: auto;
  border-radius: 10px;
  border: 1px solid #ccc;
  cursor: zoom-in;
`;

const DatasetStatistic = () => {
  const { t } = useTranslation();
  const [isOpen, setIsOpen] = useState(false);
  const [currentImage, setCurrentImage] = useState("");

  const micImages = [
    "/mic1.jpg", "/mic2.jpg", "/mic3.jpg", "/mic4.jpg", "/mic5.jpg", "/mic6.jpg", "/mic7.jpg"
  ];

  const amrImages = [
    "/amrplot1.jpg", "/amrplot2.jpg", "/amrplot3.jpg", "/amrplot4.jpg", "/amrplot5.jpg", "/amrplot6.jpg", "/amrplot7.jpg"
  ];

  const vFactorImages = [
    "/vfactor1.jpg", "/vfactor2.jpg", "/vfactor3.jpg", "/vfactor4.jpg", "/vfactor5.jpg", "/vfactor6.jpg", "/vfactor7.jpg", "/vfactor8.jpg", "/vfactor9.jpg"
  ];

  const handleImageClick = (src) => {
    setCurrentImage(src);
    setIsOpen(true);
  };

  return (
    <Container>
      <Title>{t("datasetStatistic.title")}</Title>
      <SectionTitle>MIC</SectionTitle>
      <div>
        {micImages.map((src, index) => (
          <ImageWrapper key={`mic-${index}`}>
            <StyledImage 
              src={src} 
              alt={`MIC Image ${index + 1}`} 
              onDoubleClick={() => handleImageClick(src)} 
            />
          </ImageWrapper>
        ))}
      </div>

      <SectionTitle>AMR Plot</SectionTitle>
      <div>
        {amrImages.map((src, index) => (
          <ImageWrapper key={`amr-${index}`}>
            <StyledImage 
              src={src} 
              alt={`AMR Plot ${index + 1}`} 
              onDoubleClick={() => handleImageClick(src)} 
            />
          </ImageWrapper>
        ))}
      </div>

      {/* VFactor Plot Images */}
      <SectionTitle>VFactor Plot</SectionTitle>
      <div>
        {vFactorImages.map((src, index) => (
          <ImageWrapper key={`vfactor-${index}`}>
            <StyledImage 
              src={src} 
              alt={`VFactor Plot ${index + 1}`} 
              onDoubleClick={() => handleImageClick(src)} 
            />
          </ImageWrapper>
        ))}
      </div>
      {isOpen && (
        <Lightbox
          mainSrc={currentImage}
          onCloseRequest={() => setIsOpen(false)}
          imageCaption="Statistic Image"
        />
      )}
    </Container>
  );
};

export default DatasetStatistic;
